// Canonical URL form used for dedupe (spec §5.2).
//
// This file is the single source of truth: scripts/build-wf20.js inlines the
// function body into WF-20's Canonicalize node, so the tests in
// tests/canonicalize.test.js exercise exactly what runs in production.
//
// No URL/URLSearchParams — the n8n task-runner sandbox has neither.

// `src` joins the list for the same reason as `source`: it is overwhelmingly a
// referrer tag (?src=twitter), and leaving it in split one page into two feed
// items during testing.
const STRIP = /^(utm_.*|fbclid|gclid|ref|source|src|mc_cid|mc_eid|igshid)$/i;

// Every YouTube URL shape for one video (watch?v=, youtu.be/, shorts/, embed/,
// live/, m. and music. hosts) collapses to one key, with pp/si/t/list dropped:
// otherwise the same video pasted twice became two feed items.
const YT_ID = /^(?:https?:\/\/)?(?:(?:www|m|music)\.)?(?:youtube\.com\/(?:watch\?(?:[^#]*&)?v=|shorts\/|embed\/|live\/|v\/)|youtu\.be\/)([A-Za-z0-9_-]{11})(?![A-Za-z0-9_-])/i;
function youtubeId(rawUrl) {
  const m = String(rawUrl || '').trim().match(YT_ID);
  return m ? m[1] : null;
}

function canon(rawUrl) {
  try {
    const yt = youtubeId(rawUrl);
    if (yt) return 'https://www.youtube.com/watch?v=' + yt;
    const s = String(rawUrl).trim();
    const m = s.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):\/\/([^/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/);
    if (!m) return null;
    const scheme = m[1].toLowerCase();
    let hostport = m[2];
    let path = m[3] || '/';
    const query = m[4] ? m[4].slice(1) : '';
    let userinfo = '';
    const at = hostport.lastIndexOf('@');
    if (at !== -1) { userinfo = hostport.slice(0, at + 1); hostport = hostport.slice(at + 1); }
    let host = hostport;
    let port = '';
    const ci = hostport.lastIndexOf(':');
    if (ci !== -1 && /^\d+$/.test(hostport.slice(ci + 1))) { host = hostport.slice(0, ci); port = hostport.slice(ci); }
    host = host.toLowerCase();
    if (host.startsWith('amp.')) host = host.slice(4);
    if ((scheme === 'http' && port === ':80') || (scheme === 'https' && port === ':443')) port = '';
    path = path.replace(/\/amp(\/|$)/, '$1');
    path = path.replace(/\/{2,}/g, '/');
    if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
    if (!path) path = '/';
    const params = query ? query.split('&').filter(p => p !== '' && !STRIP.test(p.split('=')[0])) : [];
    const qs = params.length ? '?' + params.join('&') : '';
    return scheme + '://' + userinfo + host + port + path + qs;
  } catch (e) { return null; }
}

let lastErr = null;
const runId = $input.first().json.run_id;
const urls = $('WF Input').first().json.urls || [];
const out = [];
for (const item of urls) {
  const obj = typeof item === 'string' ? { url: item } : (item || {});
  const c = obj.url ? canon(obj.url) : null;
  if (!c) continue;
  out.push({ json: { url: obj.url, title: obj.title || null, source: obj.source || null,
    published_at: obj.published_at || null, canonical_url: c, run_id: runId,
    slides: Boolean(obj.slides), transcribe: Boolean(obj.transcribe) } });
}
if (!out.length) return [{ json: { __no_new: true, run_id: runId, debug: lastErr } }];
return out;

const first = $input.first().json;
if (first.__no_new) return [{ json: { query: 'select null as canonical_url where false', __no_new: true } }];
const esc = (u) => String(u).replace(/'/g, "''");
const urls = $input.all().map(i => i.json.canonical_url);
const query = 'select canonical_url from seen_urls where canonical_url in (' +
  urls.map(u => "'" + esc(u) + "'").join(',') + ')';
return [{ json: { query } }];

// Media links (YouTube, podcasts, audio) in WF-20: detection, the transcript
// markdown that triage reads, the key-points skill, and the Telegram message.
// Inlined into WF-20 Code nodes; tests/media.test.js covers it.
//
// The transcript itself comes from media/server.py (native on Windows):
// human captions -> auto-captions -> Parakeet speech-to-text.

// Hosts yt-dlp handles that carry talk worth summarising. Direct audio files
// count too (a podcast episode's enclosure URL).
const MEDIA_HOST = /^https?:\/\/(?:[a-z0-9-]+\.)*(?:youtube\.com|youtu\.be|vimeo\.com|soundcloud\.com|podcasts\.apple\.com|twitch\.tv|ted\.com\/talks|rumble\.com)(?:[\/?#]|$)/i;
const AUDIO_FILE = /\.(mp3|m4a|aac|wav|ogg|opus|flac|mp4|webm)(\?|#|$)/i;
// YouTube pages that are not one video (channels, playlists, search) are not media items
const YT_NOT_VIDEO = /youtube\.com\/(?:@|c\/|channel\/|user\/|playlist|results|feed)/i;

function isMediaUrl(url) {
  const u = String(url || '').trim();
  if (!/^https?:\/\//i.test(u) || YT_NOT_VIDEO.test(u)) return false;
  return MEDIA_HOST.test(u) || AUDIO_FILE.test(u.split('?')[0] + (u.includes('?') ? '?' : ''));
}

// One Telegram message -> every link in it (n >= 1, in order, deduped) plus
// the trigger words Wasim chose (2026-10-11):
//   slides | deck | presentation | watch | look  -> also read the screen
//   transcribe | listen | hear                   -> speech-to-text on the audio
// Links are cut out before matching: "watch" is in every youtube.com/watch URL.
const SLIDE_WORDS = /\b(slides?|decks?|presentations?|watch(ing)?|look(ing)?)\b/i;
const TRANSCRIBE_WORDS = /\b(transcribe|transcription|listen(ing)?|hear(ing)?)\b/i;
function parseMediaRequest(text, extraUrl) {
  const raw = String(text || '');
  const found = raw.match(/https?:\/\/[^\s<>"')\]]+/gi) || [];
  if (extraUrl && /^https?:\/\//i.test(String(extraUrl).trim())) found.push(String(extraUrl).trim());
  const seen = new Set();
  const urls = [];
  for (let u of found) {
    u = u.replace(/[.,;:!?]+$/, '');
    if (!seen.has(u)) { seen.add(u); urls.push(u); }
  }
  const words = raw.replace(/https?:\/\/[^\s<>"')\]]+/gi, ' ');
  return { urls, slides: SLIDE_WORDS.test(words), transcribe: TRANSCRIBE_WORDS.test(words) };
}

function mmss(seconds) {
  const s = Math.max(0, Math.floor(Number(seconds) || 0));
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
  const p = (n) => String(n).padStart(2, '0');
  return h ? h + ':' + p(m) + ':' + p(sec) : m + ':' + p(sec);
}

// "1:02:05" / "12:30" / "45" -> seconds, or null
function parseTs(t) {
  const m = String(t == null ? '' : t).trim().replace(/^\[|\]$/g, '').match(/^(?:(\d+):)?(\d{1,2}):(\d{2})$|^(\d+)$/);
  if (!m) return null;
  if (m[4] != null) return Number(m[4]);
  return Number(m[1] || 0) * 3600 + Number(m[2]) * 60 + Number(m[3]);
}

const SOURCE_LABEL = { 'captions-manual': 'creator captions', 'captions-auto': 'YouTube auto-captions', parakeet: 'speech-to-text (Parakeet)' };

// What triage reads: a header the model can cite, then [m:ss] paragraphs.
function mediaMarkdown(t) {
  const lines = [];
  lines.push('# ' + (t.title || 'Untitled'));
  const meta = [t.channel && 'Channel: ' + t.channel, t.duration && 'Length: ' + mmss(t.duration),
    t.published_at && 'Published: ' + t.published_at, 'Transcript: ' + (SOURCE_LABEL[t.source] || t.source)].filter(Boolean);
  lines.push(meta.join(' | '));
  if (t.chapters && t.chapters.length) {
    lines.push('', '## Chapters');
    for (const c of t.chapters) lines.push('[' + mmss(c.start) + '] ' + c.title);
  }
  if (t.slides && t.slides.length) {
    lines.push('', '## On screen (slides, charts, code; machine-read from video frames, may contain misreads)');
    for (const s of t.slides) lines.push('[' + mmss(s.start) + '] ' + s.text);
  }
  lines.push('', '## Transcript');
  for (const p of t.paragraphs || []) lines.push('[' + mmss(p.start) + '] ' + p.text);
  return lines.join('\n');
}

// Merged into the triage call for media documents (same mechanism as query skills).
const MEDIA_SKILL_PROMPT =
  'This CONTENT is a timestamped transcript of a video or podcast. Lines start with [m:ss]. ' +
  'In addition to the standard fields, return key_points: 6 to 12 of the most important, concrete points ' +
  '(claims, numbers, names, decisions, how-tos), in the order they are made. For each, t is the [m:ss] timestamp ' +
  'of the transcript line where it is made, copied exactly from the transcript (never invented), and point is one ' +
  'self-contained sentence. Prefer specifics over generalities; skip intros, sponsor reads and calls to subscribe. ' +
  'The On screen section is machine-read from video frames: use it for figures and names shown on slides, but when it ' +
  'disagrees with what is said in the transcript, trust the transcript.';
const MEDIA_SKILL_SCHEMA = {
  key_points: { type: 'array', items: { type: 'object', additionalProperties: false,
    properties: { t: { type: 'string' }, point: { type: 'string' } }, required: ['t', 'point'] } }
};

// Link that opens the video at a moment. YouTube only; other hosts get none.
function timeLink(canonicalUrl, seconds) {
  const m = String(canonicalUrl || '').match(/youtube\.com\/watch\?v=([A-Za-z0-9_-]{11})/);
  return m ? 'https://youtu.be/' + m[1] + '?t=' + Math.floor(seconds) : null;
}

// The 9B gets the facts right but approximates timestamps (measured on the IBM
// video: 2 of 4 checked points pointed at the wrong moment, one at a time that
// is not in the transcript). Snap each point to the transcript line that shares
// the most words with it, preferring lines near the model's guess; keep the
// model's time when nothing matches well.
const STOP = new Set(['the', 'and', 'for', 'that', 'this', 'with', 'are', 'was', 'from', 'they', 'you', 'have', 'has',
  'its', 'into', 'than', 'then', 'their', 'there', 'which', 'what', 'when', 'will', 'can', 'not', 'but', 'more', 'about', 'each']);
const words = (s) => new Set(String(s).toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/)
  .filter((w) => (w.length >= 3 || /\d/.test(w)) && !STOP.has(w)));

function transcriptLines(markdown) {
  const out = [];
  const body = String(markdown || '').split('## Transcript')[1] || '';
  for (const line of body.split('\n')) {
    const m = line.match(/^\[(\d+(?::\d{2}){1,2})\]\s*(.*)$/);
    if (m) out.push({ start: parseTs(m[1]), words: words(m[2]) });
  }
  return out;
}

function snapKeyPoints(points, markdown) {
  const lines = transcriptLines(markdown);
  if (!lines.length || !Array.isArray(points)) return points || [];
  // Measured on the IBM video's 10 points: the model's own times 4/10 right;
  // best-overlap snapping 8/10 right + 1 off by one 30s paragraph. (Trusting
  // the model's time whenever it names a real line scored worse: 1:58 and
  // 7:49 are real lines that share generic words with the wrong points.)
  return points.map((p) => {
    const pw = words(p.point);
    const guess = parseTs(p.t);
    let best = null, bestScore = 0;
    for (const l of lines) {
      let overlap = 0;
      for (const w of pw) if (l.words.has(w)) overlap++;
      const near = guess == null ? 0 : Math.max(0, 1 - Math.abs(l.start - guess) / 120) * 0.5;
      const score = overlap + near;
      if (score > bestScore) { bestScore = score; best = l; }
    }
    // need real lexical evidence (>= 3 shared words) to override the model
    if (best && bestScore >= 3) return { t: mmss(best.start), point: p.point };
    return { t: guess == null ? p.t : mmss(guess), point: p.point };
  });
}

// Telegram (HTML parse mode) message for one summarised media item.
function mediaMessage(item) {
  const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const head = '\u{1F3AC} <b>' + esc(item.title) + '</b>' + (item.score != null ? '  (score ' + item.score + '/10)' : '');
  const out = [head];
  if (item.summary) out.push('', esc(item.summary));
  const pts = Array.isArray(item.key_points) ? item.key_points : [];
  if (pts.length) {
    out.push('', '<b>Key points</b>');
    for (const p of pts) {
      const sec = parseTs(p.t);
      const link = sec == null ? null : timeLink(item.canonical_url, sec);
      const stamp = sec == null ? '' : (link ? '<a href="' + link + '">' + mmss(sec) + '</a> ' : mmss(sec) + ' ');
      out.push('• ' + stamp + esc(p.point));
    }
  }
  if (item.transcript_source) out.push('', '<i>from ' + esc(SOURCE_LABEL[item.transcript_source] || item.transcript_source) + '</i>');
  return out.join('\n').slice(0, 4000);   // Telegram's limit is 4096
}


const runId = $('Create run').first().json.run_id;
const seen = new Set($input.all().map(i => i.json && i.json.canonical_url).filter(Boolean));
let candidates = [];
try { candidates = $('Canonicalize').all().map(i => i.json).filter(j => !j.__no_new); } catch (e) {}
const byCanon = new Map();
// A media link that asks for more (slides / transcribe) is processed again even
// when already in the feed; Insert doc then replaces the old rows.
const wantsMore = (c) => isMediaUrl(c.canonical_url) && (c.slides || c.transcribe);
for (const c of candidates) if ((!seen.has(c.canonical_url) || wantsMore(c)) && !byCanon.has(c.canonical_url)) byCanon.set(c.canonical_url, c);
const fresh = [...byCanon.values()];
if (!fresh.length) return [{ json: { __no_new: true, run_id: runId } }];
return fresh.map(j => ({ json: { ...j, is_media: isMediaUrl(j.canonical_url), replace: seen.has(j.canonical_url) } }));

// Triage system prompt + response schema, shared by the build scripts so WF-20
// (live pipeline) and WF-30 (backlog drain) can never drift apart.
//
// v2 (2026-07-26): two judgement axes replace the single `relevance` score,
// which collapsed — on a real query ("AI infrastructure costs") 10 of 10 items
// scored 5, so min_relevance filtered nothing. `relevance` is still emitted
// alongside for A/B comparison and will be dropped once the axes are trusted.
//
// Deliberately NOT an axis: novelty. exa and brave return a publication date on
// ~100% of results, so recency is exact SQL arithmetic on published_at rather
// than a 9B model's guess. The prompt still receives the dates so it does not
// invent recency inside the summary.
//
// The beat — what the writer actually covers — is personal editorial
// configuration and stays out of the repo. beat.md (gitignored; one paragraph
// of plain prose, no quotes/backticks/backslashes) is substituted for
// __BEAT__ by scripts/deploy.js. Copy beat.example.md to beat.md to start.
const BEAT = '__BEAT__';

const TRIAGE_SYSTEM = [
  'You are a research triage assistant for a writer covering: ' + BEAT,
  'The audience is practitioners — people who build and operate these systems,',
  'not general readers. Score every article against that beat, not general',
  'interest.',
  '',
  'You read one scraped article and return ONLY a JSON object with exactly these',
  'fields, in this order:',
  '',
  'summary: 2-3 sentences on what the article actually says. Substance only — no',
  'meta-commentary about the article itself.',
  '',
  'angle: one sentence naming the specific, publishable hook this gives the writer',
  'for that audience. Use null if there is no defensible angle beyond restating',
  'the article.',
  '',
  'relevance (integer 1-5): overall usefulness to that beat.',
  '',
  'specificity (integer 1-5): how well anchored the claims are.',
  '  5 = concrete data points, named companies and people, quantified outcomes,',
  '      verifiable claims.',
  '  3 = a mix — some claims backed, some asserted.',
  '  1 = entirely abstract commentary, opinion, or speculation with nothing to',
  '      check. Vendor content marketing and SEO listicles that recycle public',
  '      figures without sourcing belong at 1-2.',
  '',
  'angle_strength (integer 1-5): how good the angle you just wrote actually is.',
  '  5 = supports a contrarian, non-obvious, or counterintuitive take that most',
  '      commentators would miss.',
  '  3 = a viable angle, but the obvious one most people would write.',
  '  1 = no defensible angle. If angle is null, angle_strength is 1.',
  '',
  'tags: array of 1-5 short lowercase kebab-case topic tags (e.g. "ai-agents",',
  '"frontier-markets", "inference-cost"). No spaces, no punctuation.',
  '',
  'Scoring rules:',
  '- specificity and angle_strength are independent. Judge each on its own',
  '  evidence and do not let one pull the other. An article often deserves a high',
  '  score on one and a low score on the other; that spread is the point.',
  '- Most articles are not 5s. A typical useful article lands at 2-4. Reserve 5',
  '  for cases that clearly meet its anchor.',
  '- If the content is unusable — a paywall stub, error page, login wall, or a',
  '  navigation/index/listing page with no article body — set angle to null, set',
  '  all scores to 1, and say so in the summary.',
  '',
  'Return nothing except the JSON object.'
].join('\n');

// Property order is load-bearing: grammar-constrained decoding emits fields in
// schema order, so summary forces a real read before any number is committed,
// and angle_strength comes after the angle it rates.
const TRIAGE_SCHEMA = {
  type: 'json_schema',
  json_schema: {
    name: 'triage', strict: true,
    schema: {
      type: 'object',
      properties: {
        summary: { type: 'string' },
        angle: { type: ['string', 'null'] },
        relevance: { type: 'integer', minimum: 1, maximum: 5 },
        specificity: { type: 'integer', minimum: 1, maximum: 5 },
        angle_strength: { type: 'integer', minimum: 1, maximum: 5 },
        tags: { type: 'array', items: { type: 'string' }, minItems: 1, maxItems: 5 }
      },
      required: ['summary', 'angle', 'relevance', 'specificity', 'angle_strength', 'tags'],
      additionalProperties: false
    }
  }
};

const TRIAGE_MODEL = 'qwen/qwen3.5-9b';

// Per-source triage profiles.
//
// MEASURED, 2026-07-27 — read this before tuning, it is counter-intuitive:
// triage time tracks the model's REASONING OUTPUT, not how much you feed it.
// Same document at three read lengths: 2500 chars/2835 tokens/38.7s,
// 6000/4113/47.4s, 8000/2779/32.3s. The longest read was the fastest.
// Qwen spends ~3000 tokens thinking to produce ~120 tokens of JSON, and that
// is where the ~33s goes.
//
// CORRECTED 2026-10-09: thinking IS switchable per request in LM Studio 0.4.x,
// but only via `reasoning_effort` — 'none' turns it off, and ANY other value
// ('low' included) turns it on. chat_template_kwargs, /no_think and
// enable_thinking are still ignored. (The July note said reasoning_effort was
// ignored too; that test used 'minimal' with thinking already on, so it could
// not have shown a difference.)
//
// LM Studio's default for this model is now thinking OFF, so the Telegram
// router (which cannot send reasoning_effort through n8n's chat-model node)
// answers in under a second. Triage depends on thinking, so every profile
// asks for it explicitly — drop `reasoning_effort` and triage silently goes
// thinking-free.
//
// So `content_chars` does NOT buy speed. It buys judgement quality and context
// budget, which is still worth varying: a feed blurb has nothing after 2500
// chars, a hand-picked URL deserves the full read.
//
// The one real speed/cost lever is `model`. LM Studio serves every loaded
// model on the same endpoint with the same key, so pointing a source at a
// different model needs no new credential or URL — just `lms load <id>` first.
// If the named model is not loaded the request fails, retries, and falls back
// to TRIAGE_FAILED, so a missing model degrades rather than breaks.
//
// max_tokens is a ceiling, not a target — the model stops on its own well
// below it. Keep it above ~2500 or the reasoning strands the JSON.
const TRIAGE_REASONING = 'medium';
const profile = (content_chars, max_tokens) =>
  ({ model: TRIAGE_MODEL, content_chars, max_tokens, reasoning_effort: TRIAGE_REASONING });

const TRIAGE_PROFILES = {
  // Feed items are short and mostly low-signal; a smaller read is plenty.
  rss:     profile(2500, 3000),
  // Search hits on the standing queries are the material worth thinking about.
  exa:     profile(6000, 6000),
  tavily:  profile(6000, 6000),
  brave:   profile(6000, 6000),
  // A URL pasted by hand was chosen deliberately — read it properly.
  manual:  profile(8000, 6000),
  // Media transcripts (shared/media.js): 60k chars ~ 30+ min of talk with
  // timestamps, ~15k tokens. The key-points list needs room in the output.
  media:   profile(60000, 9000),
  default: profile(6000, 6000)
};

function profileFor(source) {
  const key = String(source || '').toLowerCase().trim();
  return TRIAGE_PROFILES[key] || TRIAGE_PROFILES.default;
}


// Validation of the triage model's reply. Inlined into WF-21 by
// scripts/build-wf20.js; covered by tests/triage-validate.test.js.

// Qwen puts chain-of-thought in reasoning_content. When it thinks past the
// token budget, `content` comes back empty with the JSON stranded in there —
// recover it rather than burning a retry.
function parseContent(j) {
  try {
    const msg = (j && j.choices && j.choices[0] && j.choices[0].message) || {};
    let c = msg.content;
    if (!c && msg.reasoning_content) {
      const m = String(msg.reasoning_content).match(/\{[\s\S]*\}/);
      if (m) c = m[0];
    }
    if (!c) return null;
    c = String(c).trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
    const o = JSON.parse(c);
    const ok = (v) => Number.isInteger(v) && v >= 1 && v <= 5;
    if (o && typeof o.summary === 'string' && ok(o.relevance) &&
        ok(o.specificity) && ok(o.angle_strength) &&
        Array.isArray(o.tags) && o.tags.length >= 1) return o;
    return null;
  } catch (e) { return null; }
}

// Postgres array literal. Tags arrive from a model, so treat them as hostile:
// braces, quotes, commas and backslashes would all corrupt the literal.
function tagsPg(tags) {
  const clean = (tags || []).slice(0, 5)
    .map(t => String(t).toLowerCase().replace(/[{}",\\]/g, '').trim())
    .filter(Boolean);
  return '{' + clean.join(',') + '}';
}

// The six fields every triage returns, skill or no skill.
const BASE_FIELDS = ['summary', 'angle', 'relevance', 'specificity', 'angle_strength', 'tags'];

// A skill widens the response schema, so the reply carries extra properties.
// Split them off into their own object: the fixed columns stay columns, the
// skill's fields go to feed_items.structured as JSON.
function splitStructured(o) {
  if (!o || typeof o !== 'object') return { structured: null };
  const structured = {};
  let any = false;
  for (const k of Object.keys(o)) {
    if (BASE_FIELDS.includes(k)) continue;
    structured[k] = o[k];
    any = true;
  }
  return { structured: any ? structured : null };
}

// Merge a skill's extra properties into the base response schema. strict mode
// requires every declared property to be listed as required, so add both.
function withSkill(baseSchema, extraProps) {
  const s = JSON.parse(JSON.stringify(baseSchema));
  if (!extraProps || typeof extraProps !== 'object') return s;
  const target = s.json_schema.schema;
  for (const [k, v] of Object.entries(extraProps)) {
    if (BASE_FIELDS.includes(k)) continue; // a skill may not redefine the core
    target.properties[k] = v;
    if (!target.required.includes(k)) target.required.push(k);
  }
  return s;
}


// Media links (YouTube, podcasts, audio) in WF-20: detection, the transcript
// markdown that triage reads, the key-points skill, and the Telegram message.
// Inlined into WF-20 Code nodes; tests/media.test.js covers it.
//
// The transcript itself comes from media/server.py (native on Windows):
// human captions -> auto-captions -> Parakeet speech-to-text.

// Hosts yt-dlp handles that carry talk worth summarising. Direct audio files
// count too (a podcast episode's enclosure URL).
const MEDIA_HOST = /^https?:\/\/(?:[a-z0-9-]+\.)*(?:youtube\.com|youtu\.be|vimeo\.com|soundcloud\.com|podcasts\.apple\.com|twitch\.tv|ted\.com\/talks|rumble\.com)(?:[\/?#]|$)/i;
const AUDIO_FILE = /\.(mp3|m4a|aac|wav|ogg|opus|flac|mp4|webm)(\?|#|$)/i;
// YouTube pages that are not one video (channels, playlists, search) are not media items
const YT_NOT_VIDEO = /youtube\.com\/(?:@|c\/|channel\/|user\/|playlist|results|feed)/i;

function isMediaUrl(url) {
  const u = String(url || '').trim();
  if (!/^https?:\/\//i.test(u) || YT_NOT_VIDEO.test(u)) return false;
  return MEDIA_HOST.test(u) || AUDIO_FILE.test(u.split('?')[0] + (u.includes('?') ? '?' : ''));
}

// One Telegram message -> every link in it (n >= 1, in order, deduped) plus
// the trigger words Wasim chose (2026-10-11):
//   slides | deck | presentation | watch | look  -> also read the screen
//   transcribe | listen | hear                   -> speech-to-text on the audio
// Links are cut out before matching: "watch" is in every youtube.com/watch URL.
const SLIDE_WORDS = /\b(slides?|decks?|presentations?|watch(ing)?|look(ing)?)\b/i;
const TRANSCRIBE_WORDS = /\b(transcribe|transcription|listen(ing)?|hear(ing)?)\b/i;
function parseMediaRequest(text, extraUrl) {
  const raw = String(text || '');
  const found = raw.match(/https?:\/\/[^\s<>"')\]]+/gi) || [];
  if (extraUrl && /^https?:\/\//i.test(String(extraUrl).trim())) found.push(String(extraUrl).trim());
  const seen = new Set();
  const urls = [];
  for (let u of found) {
    u = u.replace(/[.,;:!?]+$/, '');
    if (!seen.has(u)) { seen.add(u); urls.push(u); }
  }
  const words = raw.replace(/https?:\/\/[^\s<>"')\]]+/gi, ' ');
  return { urls, slides: SLIDE_WORDS.test(words), transcribe: TRANSCRIBE_WORDS.test(words) };
}

function mmss(seconds) {
  const s = Math.max(0, Math.floor(Number(seconds) || 0));
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
  const p = (n) => String(n).padStart(2, '0');
  return h ? h + ':' + p(m) + ':' + p(sec) : m + ':' + p(sec);
}

// "1:02:05" / "12:30" / "45" -> seconds, or null
function parseTs(t) {
  const m = String(t == null ? '' : t).trim().replace(/^\[|\]$/g, '').match(/^(?:(\d+):)?(\d{1,2}):(\d{2})$|^(\d+)$/);
  if (!m) return null;
  if (m[4] != null) return Number(m[4]);
  return Number(m[1] || 0) * 3600 + Number(m[2]) * 60 + Number(m[3]);
}

const SOURCE_LABEL = { 'captions-manual': 'creator captions', 'captions-auto': 'YouTube auto-captions', parakeet: 'speech-to-text (Parakeet)' };

// What triage reads: a header the model can cite, then [m:ss] paragraphs.
function mediaMarkdown(t) {
  const lines = [];
  lines.push('# ' + (t.title || 'Untitled'));
  const meta = [t.channel && 'Channel: ' + t.channel, t.duration && 'Length: ' + mmss(t.duration),
    t.published_at && 'Published: ' + t.published_at, 'Transcript: ' + (SOURCE_LABEL[t.source] || t.source)].filter(Boolean);
  lines.push(meta.join(' | '));
  if (t.chapters && t.chapters.length) {
    lines.push('', '## Chapters');
    for (const c of t.chapters) lines.push('[' + mmss(c.start) + '] ' + c.title);
  }
  if (t.slides && t.slides.length) {
    lines.push('', '## On screen (slides, charts, code; machine-read from video frames, may contain misreads)');
    for (const s of t.slides) lines.push('[' + mmss(s.start) + '] ' + s.text);
  }
  lines.push('', '## Transcript');
  for (const p of t.paragraphs || []) lines.push('[' + mmss(p.start) + '] ' + p.text);
  return lines.join('\n');
}

// Merged into the triage call for media documents (same mechanism as query skills).
const MEDIA_SKILL_PROMPT =
  'This CONTENT is a timestamped transcript of a video or podcast. Lines start with [m:ss]. ' +
  'In addition to the standard fields, return key_points: 6 to 12 of the most important, concrete points ' +
  '(claims, numbers, names, decisions, how-tos), in the order they are made. For each, t is the [m:ss] timestamp ' +
  'of the transcript line where it is made, copied exactly from the transcript (never invented), and point is one ' +
  'self-contained sentence. Prefer specifics over generalities; skip intros, sponsor reads and calls to subscribe. ' +
  'The On screen section is machine-read from video frames: use it for figures and names shown on slides, but when it ' +
  'disagrees with what is said in the transcript, trust the transcript.';
const MEDIA_SKILL_SCHEMA = {
  key_points: { type: 'array', items: { type: 'object', additionalProperties: false,
    properties: { t: { type: 'string' }, point: { type: 'string' } }, required: ['t', 'point'] } }
};

// Link that opens the video at a moment. YouTube only; other hosts get none.
function timeLink(canonicalUrl, seconds) {
  const m = String(canonicalUrl || '').match(/youtube\.com\/watch\?v=([A-Za-z0-9_-]{11})/);
  return m ? 'https://youtu.be/' + m[1] + '?t=' + Math.floor(seconds) : null;
}

// The 9B gets the facts right but approximates timestamps (measured on the IBM
// video: 2 of 4 checked points pointed at the wrong moment, one at a time that
// is not in the transcript). Snap each point to the transcript line that shares
// the most words with it, preferring lines near the model's guess; keep the
// model's time when nothing matches well.
const STOP = new Set(['the', 'and', 'for', 'that', 'this', 'with', 'are', 'was', 'from', 'they', 'you', 'have', 'has',
  'its', 'into', 'than', 'then', 'their', 'there', 'which', 'what', 'when', 'will', 'can', 'not', 'but', 'more', 'about', 'each']);
const words = (s) => new Set(String(s).toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/)
  .filter((w) => (w.length >= 3 || /\d/.test(w)) && !STOP.has(w)));

function transcriptLines(markdown) {
  const out = [];
  const body = String(markdown || '').split('## Transcript')[1] || '';
  for (const line of body.split('\n')) {
    const m = line.match(/^\[(\d+(?::\d{2}){1,2})\]\s*(.*)$/);
    if (m) out.push({ start: parseTs(m[1]), words: words(m[2]) });
  }
  return out;
}

function snapKeyPoints(points, markdown) {
  const lines = transcriptLines(markdown);
  if (!lines.length || !Array.isArray(points)) return points || [];
  // Measured on the IBM video's 10 points: the model's own times 4/10 right;
  // best-overlap snapping 8/10 right + 1 off by one 30s paragraph. (Trusting
  // the model's time whenever it names a real line scored worse: 1:58 and
  // 7:49 are real lines that share generic words with the wrong points.)
  return points.map((p) => {
    const pw = words(p.point);
    const guess = parseTs(p.t);
    let best = null, bestScore = 0;
    for (const l of lines) {
      let overlap = 0;
      for (const w of pw) if (l.words.has(w)) overlap++;
      const near = guess == null ? 0 : Math.max(0, 1 - Math.abs(l.start - guess) / 120) * 0.5;
      const score = overlap + near;
      if (score > bestScore) { bestScore = score; best = l; }
    }
    // need real lexical evidence (>= 3 shared words) to override the model
    if (best && bestScore >= 3) return { t: mmss(best.start), point: p.point };
    return { t: guess == null ? p.t : mmss(guess), point: p.point };
  });
}

// Telegram (HTML parse mode) message for one summarised media item.
function mediaMessage(item) {
  const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const head = '\u{1F3AC} <b>' + esc(item.title) + '</b>' + (item.score != null ? '  (score ' + item.score + '/10)' : '');
  const out = [head];
  if (item.summary) out.push('', esc(item.summary));
  const pts = Array.isArray(item.key_points) ? item.key_points : [];
  if (pts.length) {
    out.push('', '<b>Key points</b>');
    for (const p of pts) {
      const sec = parseTs(p.t);
      const link = sec == null ? null : timeLink(item.canonical_url, sec);
      const stamp = sec == null ? '' : (link ? '<a href="' + link + '">' + mmss(sec) + '</a> ' : mmss(sec) + ' ');
      out.push('• ' + stamp + esc(p.point));
    }
  }
  if (item.transcript_source) out.push('', '<i>from ' + esc(SOURCE_LABEL[item.transcript_source] || item.transcript_source) + '</i>');
  return out.join('\n').slice(0, 4000);   // Telegram's limit is 4096
}

